package com.database.societyproject.finance.controller;
import com.database.societyproject.finance.dto.*; import com.database.societyproject.finance.service.RazorpayPaymentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/razorpay") @PreAuthorize("denyAll()") public class RazorpayController { private final RazorpayPaymentService service; public RazorpayController(RazorpayPaymentService s){service=s;} @PostMapping("/orders") public ResponseEntity<GatewayOrderResponse> create(@Valid @RequestBody GatewayOrderRequest r){return ResponseEntity.status(201).body(service.create(r));} @PostMapping("/verify") public PaymentResponse verify(@Valid @RequestBody RazorpayVerificationRequest r){return service.verify(r);} @PostMapping(value="/webhook",consumes=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<Void> webhook(@RequestHeader("X-Razorpay-Signature") String signature,@RequestBody String body){service.webhook(body,signature);return ResponseEntity.ok().build();}}
